package com.ugro.skaleup.rag;
import org.springframework.stereotype.Service; import java.util.*;
@Service public class LanguageDetector { private final Map<String,Set<String>> roman=Map.of("Hindi",Set.of("kya","hai","hota","batao","kaise","kyun","kahan","mera","mujhe","aap","nahi","ka","ke","ki"),"Marathi",Set.of("kay","ahe","aahe","sanga","sang","kasa","kashi","ka","mala","tumhi","nahi","kiti"),"Bengali",Set.of("ki","ache","kemon","keno","ami","amar","apni","bolun","kothay"),"Tamil",Set.of("enna","epadi","yenga","eppudu","enakku","solunga","sollu","unga","ungal","illai"),"Kannada",Set.of("enu","yenu","hege","yelli","yavaga","eshtu","yaru","nanu","nanage","heli","beku","illa"),"Telugu",Set.of("enti","ela","enduku","ekkada","evaru","naaku","naku","cheppu","undi","ledu","kavali"));
 public String detect(String q){if(q==null||q.isBlank())return "English";int[] scores=new int[6];String[] langs={"Hindi","Marathi","Bengali","Tamil","Kannada","Telugu"};String l=q.toLowerCase();for(int i=0;i<langs.length;i++)for(String w:l.split("\\s+"))if(roman.get(langs[i]).contains(w.replaceAll("[^\\p{L}]","")))scores[i]++;for(char c:q.toCharArray()){if(c>=0x0900&&c<=0x097F)return "Hindi";if(c>=0x0980&&c<=0x09FF)return "Bengali";if(c>=0x0B80&&c<=0x0BFF)return "Tamil";if(c>=0x0C80&&c<=0x0CFF)return "Kannada";if(c>=0x0C00&&c<=0x0C7F)return "Telugu";}int best=0;for(int i=1;i<scores.length;i++)if(scores[i]>scores[best])best=i;return scores[best]>0?langs[best]:"English";}
}
